parameters.jsCode:
// Normalización y limpieza de datos para Costa Rica
const body = $input.item.json.body || $input.item.json.data || $input.item.json;
const customer = body.customer || {};

// 1. Limpieza de número telefónico (Eliminar guiones, espacios y asegurar 506)
let rawPhone = String(body.customerPhone || customer.phone || '').replace(/[^0-9]/g, '');
if (rawPhone.length === 8) {
  rawPhone = '506' + rawPhone;
} else if (rawPhone.startsWith('00506')) {
  rawPhone = rawPhone.substring(2);
}

// 2. Formato de Monto y Moneda
const currency = body.currency || 'USD';
const amount = Number(body.totalUSD || body.totalAmount || body.totalCRC || 0);
let formattedTotal = '';

if (currency === 'CRC' || body.totalCRC) {
  const crcVal = body.totalCRC || Math.round(amount * 515);
  formattedTotal = '₡' + Math.round(crcVal).toLocaleString('es-CR');
} else {
  formattedTotal = '$' + amount.toFixed(2) + ' USD';
}

// 3. Enlaces útiles según destino en Costa Rica
const tourName = body.tourName || 'Tour en Costa Rica';
const wazeSearch = encodeURIComponent(tourName + ' Costa Rica');
const wazeLink = `https://waze.com/ul?q=${wazeSearch}`;

return {
  bookingId: body.bookingId || 'CR-' + Date.now().toString().slice(-6),
  customerName: body.customerName || customer.name || 'Aventurero/a',
  customerEmail: body.customerEmail || customer.email || '',
  customerPhone: rawPhone,
  tourName: tourName,
  tourDate: body.date || body.tourDate || new Date().toISOString().split('T')[0],
  time: body.time || '08:00 AM',
  participants: (Number(body.adults || 0) + Number(body.children || 0)) || Number(body.participants || 1),
  totalFormatted: formattedTotal,
  paymentMethod: body.paymentMethod || 'Pendiente',
  wazeLink: wazeLink,
  meetingPoint: body.pickupHotel || body.meetingPoint || 'Recepción del Hotel o punto coordinado'
};

